ssh_argv:
import json,pathlib,subprocess,socket,time,re
TARGET_MAC='fc:a3:86:b3:86:72'
TARGET_USB='1-2.3:1.0'
OLD_REBIND_WALL=1794305865

def read(path):
    p=pathlib.Path(path)
    try:
        return p.read_text().strip()
    except Exception as exc:
        return 'ERROR:'+repr(exc)

def run(argv, timeout=8):
    try:
        p=subprocess.run(argv,capture_output=True,text=True,timeout=timeout)
        return dict(argv=argv,returncode=p.returncode,stdout=p.stdout,stderr=p.stderr)
    except Exception as exc:
        return dict(argv=argv,error=repr(exc))

net=[]
for p in sorted(pathlib.Path('/sys/class/net').glob('*')):
    if not p.is_dir():
        continue
    dev=(p/'device')
    resolved=str(dev.resolve()) if dev.exists() else None
    driver=str((dev/'driver').resolve()) if (dev/'driver').exists() else None
    net.append(dict(name=p.name,address=read(p/'address'),operstate=read(p/'operstate'),ifindex=read(p/'ifindex'),device=resolved,driver=driver,carrier=read(p/'carrier')))

target=[x for x in net if x['address'].lower()==TARGET_MAC]
usb_devices=[]
for p in sorted(pathlib.Path('/sys/bus/usb/devices').glob('*')):
    if not p.is_dir() or not (p/'idVendor').exists():
        continue
    usb_devices.append(dict(name=p.name,realpath=str(p.resolve()),idVendor=read(p/'idVendor'),idProduct=read(p/'idProduct'),manufacturer=read(p/'manufacturer'),product=read(p/'product'),serial=read(p/'serial'),speed=read(p/'speed'),busnum=read(p/'busnum'),devnum=read(p/'devnum'),authorized=read(p/'authorized'),configuration=read(p/'bConfigurationValue')))

target_usb=[x for x in usb_devices if x['name']==TARGET_USB]
kernel=run(['journalctl','-k','--since','@'+str(OLD_REBIND_WALL),'--no-pager','-o','short-unix'],timeout=12)
lines=kernel.get('stdout','').splitlines()
usb_events=[line for line in lines if re.search(r'(?i)(usb|error -71|unable to enumer|descriptor|disconnect|reset high|device firmware changed)',line)]
new_71=[line for line in lines if re.search(r"(?i)(error -71|unable to enumer|descriptor read|can't read configurations)",line)]
new_disconnect=[line for line in lines if re.search(r'(?i)(USB disconnect|usb .*disconnect|reset (?:high|full|super|low)-speed USB)',line)]
services={u:run(['systemctl','show',u,'-p','Id','-p','ActiveState','-p','SubState','-p','MainPID','-p','ExecMainStartTimestamp']) for u in ['wfb-fl-server-daemon.service']}
ps=run(['ps','-eo','pid=,stat=,args=','--forest'])
net_addr=run(['ip','-j','addr','show'])
net_link=run(['ip','-j','link','show','dev','enP8p1s0'])
net_mgmt_addr=run(['ip','-j','addr','show','dev','enP8p1s0'])
print(json.dumps(dict(host=socket.gethostname(),wall=time.time(),old_rebind_wall=OLD_REBIND_WALL,target_mac=TARGET_MAC,target_usb=TARGET_USB,target_netdev=target,all_netdev=net,target_usb_sysfs=target_usb,usb_devices=usb_devices,kernel_since_old_rebind=kernel,kernel_usb_event_lines=usb_events,new_error_71_lines=new_71,new_disconnect_or_reset_lines=new_disconnect,services=services,management_enP8p1s0=dict(link=net_link,addr=net_mgmt_addr),all_addr=net_addr,processes=ps),ensure_ascii=False))
